class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for(int i = 0;i<numCourses;i++){
            adj.add(new ArrayList<>());
        }
        for(int[]item:prerequisites){
            adj.get(item[1]).add(item[0]);
        }
        int[]flag = new int[numCourses];
        for(int i = 0;i<numCourses;i++){
            if(hasHuan(adj,flag,i)){
                return false;
            }
        }
        return true;
    }
    public boolean hasHuan(List<List<Integer>> adj,int[]flag,int i){
        if(flag[i]==-1){
            return false;
        }
        if(flag[i]==1){
            return true;
        }
        flag[i]=1;
        for(int j:adj.get(i)){
            if(hasHuan(adj,flag,j)){
                return true;
            }
        }
        flag[i] = -1;
        return false;
    }
}
